import React from "react";

const Pagination = ({ filter, setFilter, totalCount }) => {
    const totalPages = Math.ceil(totalCount / filter.limit);

    const changePage = (newPage) => {
        setFilter((prev) => ({ ...prev, page: newPage }));
    };

    return (
        <div className="pagination">
            <button disabled={filter.page === 0} onClick={() => changePage(filter.page - 1)}>
                Předchozí
            </button>
            <span>Strana {filter.page + 1} z {totalPages}</span>
            <button disabled={filter.page >= totalPages - 1} onClick={() => changePage(filter.page + 1)}>
                Další
            </button>
        </div>
    );
};

export default Pagination;
